const templates = $('Get row(s)').all().map(item => item.json);
const transcript = $('Transcrever (WhisperX)').first().json;
const config = $('Configurações (Mock)').first().json;
const filename = config.video_key || 'video_original.mp4';

const dataToSend = config.display_mode === 'segment' ? transcript.segments : transcript.words;


return templates.map(template => {
  return {
    json: {
      template_name: template.name || 'default',
      template_json: JSON.stringify(template),
      transcript_data: JSON.stringify(dataToSend),
      original_filename: filename
    }
  };
});

